CREATE TABLE users(id uuid PRIMARY KEY, email text NOT NULL UNIQUE, display_name text NOT NULL, role text NOT NULL CHECK(role IN ('buyer','creator','admin','viewer')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY, legal_name text NOT NULL, country text NOT NULL CHECK(country IN ('ES','DE')), verified boolean NOT NULL DEFAULT false);
CREATE TABLE organization_members(organization_id uuid REFERENCES organizations(id),user_id uuid REFERENCES users(id), role text NOT NULL CHECK(role IN ('owner','buyer','viewer')), PRIMARY KEY(organization_id,user_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE creators(id uuid PRIMARY KEY,user_id uuid NOT NULL UNIQUE REFERENCES users(id),display_name text NOT NULL,bio text NOT NULL,languages text[] NOT NULL DEFAULT '{es}',location text NOT NULL,portrait text NOT NULL,identity_status text NOT NULL DEFAULT 'pending' CHECK(identity_status IN ('pending','verified','rejected')),identity_expires_at timestamptz,adult_verified boolean NOT NULL DEFAULT false,connected_account text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assets(id uuid PRIMARY KEY,creator_id uuid NOT NULL REFERENCES creators(id),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending_review','published','rejected','suspended','archived')),relationship_status text NOT NULL DEFAULT 'pending' CHECK(relationship_status IN ('pending','reviewed','rejected')),policy_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE policies(id uuid PRIMARY KEY,asset_id uuid NOT NULL REFERENCES assets(id),version integer NOT NULL,payload jsonb NOT NULL,sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(asset_id,version),UNIQUE(asset_id,id));
ALTER TABLE assets ADD CONSTRAINT asset_policy_fk FOREIGN KEY(id,policy_id) REFERENCES policies(asset_id,id);
CREATE TABLE consents(id uuid PRIMARY KEY,policy_id uuid NOT NULL REFERENCES policies(id),user_id uuid NOT NULL REFERENCES users(id),document_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(policy_id,user_id));
CREATE TABLE asset_files(id uuid PRIMARY KEY,asset_id uuid NOT NULL REFERENCES assets(id),storage_key text NOT NULL UNIQUE,sha256 text NOT NULL,mime_type text NOT NULL,size_bytes integer NOT NULL CHECK(size_bytes>0 AND size_bytes<=2097152),scan_status text NOT NULL CHECK(scan_status IN ('pending','clean','rejected')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviews(id uuid PRIMARY KEY,asset_id uuid NOT NULL REFERENCES assets(id),actor_id uuid NOT NULL REFERENCES users(id),decision text NOT NULL CHECK(decision IN ('approve','reject')),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE requests(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),asset_id uuid NOT NULL REFERENCES assets(id),policy_id uuid NOT NULL, usage jsonb NOT NULL,usage_hash text NOT NULL,decision text NOT NULL CHECK(decision IN ('ALLOW','DENY','REQUIRES_APPROVAL')), reason_codes jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(asset_id,policy_id) REFERENCES policies(asset_id,id));
CREATE TABLE approvals(id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES requests(id),actor_id uuid NOT NULL REFERENCES users(id),usage_hash text NOT NULL,policy_hash text NOT NULL,decision text NOT NULL CHECK(decision IN ('approve','reject')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotes(id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES requests(id),scope jsonb NOT NULL,price jsonb NOT NULL,policy_hash text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders(id uuid PRIMARY KEY,quote_id uuid NOT NULL UNIQUE REFERENCES quotes(id),organization_id uuid NOT NULL REFERENCES organizations(id),asset_id uuid NOT NULL REFERENCES assets(id),status text NOT NULL CHECK(status IN ('awaiting_acceptance','awaiting_payment','payment_processing','paid','issuing','fulfilled','expired','cancelled','paid_requires_review','refund_pending','refunded')),price jsonb NOT NULL,scope jsonb NOT NULL,policy_snapshot jsonb NOT NULL,contract_text text NOT NULL,contract_hash text NOT NULL,accepted_at timestamptz,accepted_by uuid REFERENCES users(id),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contract_acceptances(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),actor_id uuid NOT NULL REFERENCES users(id),document_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,actor_id));
CREATE TABLE payment_attempts(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),provider text NOT NULL,provider_ref text UNIQUE,status text NOT NULL CHECK(status IN ('creating','pending','processing','succeeded','failed','expired')),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_open_payment ON payment_attempts(order_id) WHERE status IN ('creating','pending','processing');
CREATE TABLE provider_events(id uuid PRIMARY KEY,provider text NOT NULL,event_id text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done','failed')),error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,event_id));
CREATE TABLE outbox(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),kind text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done','dead')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),last_error text,UNIQUE(order_id,kind));
CREATE TABLE licenses(id uuid PRIMARY KEY,order_id uuid NOT NULL UNIQUE REFERENCES orders(id),public_token text NOT NULL UNIQUE,status text NOT NULL CHECK(status IN ('issued','suspended','revoked')),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,payload jsonb NOT NULL,signature text NOT NULL,key_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE TABLE license_status_events(id uuid PRIMARY KEY,license_id uuid NOT NULL REFERENCES licenses(id),actor_id uuid NOT NULL REFERENCES users(id),status text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE journals(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),kind text NOT NULL,currency text NOT NULL CHECK(currency='EUR'),created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,kind));
CREATE TABLE ledger_entries(id uuid PRIMARY KEY,journal_id uuid NOT NULL REFERENCES journals(id),account text NOT NULL,side text NOT NULL CHECK(side IN ('debit','credit')),amount_minor bigint NOT NULL CHECK(amount_minor>0));
CREATE FUNCTION check_journal_balance() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE jid uuid; deb bigint; cred bigint; n bigint;
BEGIN
jid := CASE WHEN TG_TABLE_NAME='journals' THEN NEW.id ELSE NEW.journal_id END;
SELECT count(*),coalesce(sum(amount_minor) FILTER(WHERE side='debit'),0),coalesce(sum(amount_minor) FILTER(WHERE side='credit'),0) INTO n,deb,cred FROM ledger_entries WHERE journal_id=jid;
IF n<2 OR deb<>cred THEN RAISE EXCEPTION 'Unbalanced journal %',jid; END IF;
RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER balanced_journal AFTER INSERT ON journals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_journal_balance();
CREATE CONSTRAINT TRIGGER balanced_entries AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_journal_balance();
CREATE TABLE refunds(id uuid PRIMARY KEY,order_id uuid NOT NULL UNIQUE REFERENCES orders(id),reason text NOT NULL,status text NOT NULL,provider_ref text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incidents(id uuid PRIMARY KEY,reporter_id uuid REFERENCES users(id),asset_id uuid REFERENCES assets(id),license_id uuid REFERENCES licenses(id),category text NOT NULL,details text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id uuid PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,resource_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_records(actor_id uuid NOT NULL,route text NOT NULL,key text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,route,key));
CREATE TABLE favorites(user_id uuid REFERENCES users(id),asset_id uuid REFERENCES assets(id),PRIMARY KEY(user_id,asset_id));
CREATE FUNCTION reject_evidence_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Evidence is append only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['policies','consents','reviews','approvals','quotes','contract_acceptances','license_status_events','journals','ledger_entries','audit_events'] LOOP EXECUTE format('CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION reject_evidence_mutation()',t); END LOOP; END $$;
CREATE INDEX published_assets ON assets(created_at) WHERE status='published';
CREATE INDEX requests_org ON requests(organization_id);
CREATE INDEX requests_asset ON requests(asset_id);
CREATE INDEX orders_org ON orders(organization_id);
CREATE INDEX orders_asset ON orders(asset_id);
CREATE INDEX pending_events ON provider_events(created_at) WHERE status='pending';
CREATE INDEX pending_outbox ON outbox(available_at) WHERE status='pending';
